// Minimal WebSocket client test for in-order sequence_id
const ws = new WebSocket('wss://api.example/notifications?tenant=abc');
let last = 0;
ws.onmessage = (e) => {
  const m = JSON.parse(e.data);
  if (m.sequence_id !== last + 1) throw new Error('out of order');
  last = m.sequence_id;
};
```

